30	    dist: String,
31	
32	    /// Log directory
33	    #[arg(long, default_value = "logs")]
34	    log_dir: String,
35	
36	    /// Enable release mode (reduced stdout logging, info-level file logging)
37	    #[arg(long)]
38	    release_mode: bool,
39	}
40	
41	#[tokio::main]
42	async fn main() {
43	    raise_fd_limit();
44	
45	    let args = Args::parse();
46	
47	    // Initialize logging — guards must live until program exit
48	    let _log_guards = logging::init(&args.log_dir, args.release_mode);
49	
50	    // Start file watcher (background thread)
51	    let watcher_tx = watcher::start_watching();
52	
53	    let api = router::build_api_router(watcher_tx, args.log_dir.clone());
54	
55	    let index_path = std::path::PathBuf::from(&args.dist).join("index.html");
56	    let spa_fallback = tower::service_fn(move |_req: http::Request<_>| {
57	        let index = index_path.clone();
58	        async move {
59	            match tokio::fs::read(&index).await {
60	                Ok(body) => Ok(http::Response::builder()
61	                    .header("content-type", "text/html; charset=utf-8")
62	                    .header("cache-control", "no-cache, no-store, must-revalidate")
63	                    .body(axum::body::Body::from(body))
64	                    .unwrap()),
65	                Err(_) => Ok(http::Response::builder()
66	                    .status(404)
67	                    .body(axum::body::Body::from("index.html not found"))
68	                    .unwrap()),
69	            }
70	        }
71	    });
72	
73	    let app = Router::new()
74	        .nest("/api", api)
75	        .fallback_service(
76	            ServeDir::new(&args.dist)
77	                .append_index_html_on_directories(true)
78	                .fallback(spa_fallback),
79	        )
80	        .layer(PropagateRequestIdLayer::x_request_id())
81	        .layer(
82	            TraceLayer::new_for_http()
83	                .make_span_with(|request: &http::Request<_>| {
84	                    let request_id = request
85	                        .headers()
86	                        .get("x-request-id")
87	                        .and_then(|v| v.to_str().ok())
88	                        .unwrap_or("none");
89	                    tracing::info_span!(
90	                        "http",
91	                        method = %request.method(),
92	                        path = %request.uri().path(),
93	                        request_id = %request_id,
94	                    )
95	                })
96	                .on_response(
97	                    tower_http::trace::DefaultOnResponse::new()
98	                        .level(tracing::Level::INFO)
99	                        .latency_unit(tower_http::LatencyUnit::Millis),
100	                )
101	                .on_failure(
102	                    tower_http::trace::DefaultOnFailure::new().level(tracing::Level::ERROR),
103	                ),
104	        )
105	        .layer(SetRequestIdLayer::x_request_id(MakeRequestUuid))
106	        .layer(CorsLayer::permissive());
107	
108	    let addr = SocketAddr::from(([127, 0, 0, 1], args.port));
109	    tracing::info!("agent-panel-server listening on http://{}", addr);
110	
111	    if !args.no_open {
112	        let url = format!("http://127.0.0.1:{}", args.port);
113	        let _ = open::that(&url);
114	    }
115	
116	    let listener = tokio::net::TcpListener::bind(addr).await.unwrap();
117	    axum::serve(listener, app).await.unwrap();
118	}
119	
120	/// Raise the file descriptor limit to avoid "Too many open files" when the
121	/// file watcher recursively monitors directories with many entries.
122	#[cfg(unix)]
123	fn raise_fd_limit() {
124	    use std::io;
125	    let mut rlim = libc::rlimit {
126	        rlim_cur: 0,
127	        rlim_max: 0,
128	    };
129	    unsafe {
130	        if libc::getrlimit(libc::RLIMIT_NOFILE, &mut rlim) == 0 {
131	            let target = rlim.rlim_max.min(10240);
132	            if rlim.rlim_cur < target {
133	                rlim.rlim_cur = target;
134	                if libc::setrlimit(libc::RLIMIT_NOFILE, &rlim) != 0 {
135	                    eprintln!(
136	                        "warning: failed to raise fd limit: {}",
137	                        io::Error::last_os_error()
138	                    );
139	                }
140	            }
141	        }
142	    }
143	}
144	
145	#[cfg(not(unix))]
146	fn raise_fd_limit() {}
