        let thread = std::thread::current();
        let timestamp = chrono::Local::now().format("%Y-%m-%d %H:%M:%S%.3f");

        let payload = if let Some(s) = info.payload().downcast_ref::<&str>() {
            s.to_string()
        } else if let Some(s) = info.payload().downcast_ref::<String>() {
            s.clone()
        } else {
            "unknown panic".to_string()
        };

        let location = info
            .location()
            .map(|l| format!("{}:{}:{}", l.file(), l.line(), l.column()))
            .unwrap_or_else(|| "unknown location".to_string());

        let mut msg = String::new();
        msg.push_str("=== Crash Report ===\n");
        msg.push_str(&format!("Timestamp: {}\n", timestamp));
        msg.push_str(&format!(
            "OS: {} {}\n",
            std::env::consts::OS,
            std::env::consts::ARCH
        ));
        msg.push_str(&format!(
            "Thread: {:?} (id: {:?})\n",
            thread.name(),
            thread.id()
        ));
        msg.push_str(&format!("Location: {}\n", location));
        msg.push_str(&format!("Panic: {}\n", payload));
        msg.push_str(&format!(
            "Backtrace:\n{:?}\n",
            std::backtrace::Backtrace::force_capture()
        ));
        msg.push_str("=== End Crash Report ===\n\n");

        // 写入 crash.log（追加模式）
        if let Ok(mut f) = std::fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(&log_path)
        {
            let _ = writeln!(f, "{}", msg);
        }

        // 同时输出到 stderr
        eprintln!("{}", msg);

        // 调用默认 hook（打印到 stderr）
        default_hook(info);
    }));

    // 确保 backtrace 在 release 模式下也可用
    if std::env::var("RUST_BACKTRACE").is_err() {
        std::env::set_var("RUST_BACKTRACE", "1");
    }
}

