/// 创建隔离的测试服务器
///
/// 每次调用创建独立的 TempDir 作为 log 目录，
/// 避免测试之间互相干扰。
pub fn create_test_server() -> (TestServer, TempDir) {
    let dir = TempDir::new().expect("failed to create temp dir");
    let (tx, _) = broadcast::channel(256);
    let router = agent_panel_server::build_api_router_for_test(tx, dir.path().to_str().unwrap());
    let server = TestServer::new(router.into_make_service());
    (server, dir)
}

/// 创建测试用的 JSONL session 文件
///
/// 在指定目录下创建一个模拟的 Claude Code session 文件，
/// 包含 user + assistant 消息。
pub fn create_test_session_file(dir: &PathBuf, filename: &str, content: &str) -> PathBuf {
    let file_path = dir.join(filename);
    std::fs::write(&file_path, content).expect("failed to write test session file");
    file_path
}

/// 生成最小可用的 session JSONL 内容
pub fn sample_session_jsonl() -> String {
    let mut lines = Vec::new();

    // Session metadata
    lines.push(serde_json::json!({
        "type": "summary",
        "session_id": "test-session-001",
        "cwd": "/test/project",
        "git_branch": "main",
        "model": "claude-sonnet-4",
        "timestamp": "2026-01-01T00:00:00Z"
    }).to_string());

    // User message
    lines.push(serde_json::json!({
        "type": "message",
        "uuid": "msg-001",
        "message": {
            "role": "user",
            "content": "Hello, test!"
        },
        "timestamp": "2026-01-01T00:00:01Z"
    }).to_string());

    // Assistant message
    lines.push(serde_json::json!({
        "type": "message",
        "uuid": "msg-002",
        "message": {
            "role": "assistant",
            "content": "Hi! This is a test response."
        },
        "timestamp": "2026-01-01T00:00:02Z"
    }).to_string());

    lines.join("\n")
}

