use axum::Router;
use clap::Parser;
use std::net::SocketAddr;
use tower_http::cors::CorsLayer;
use tower_http::request_id::{MakeRequestUuid, PropagateRequestIdLayer, SetRequestIdLayer};
use tower_http::services::ServeDir;
use tower_http::trace::TraceLayer;

#[derive(Parser, Debug)]
#[command(name = "agent-panel-server", about = "Agent Panel Rust backend")]
struct Args {
    /// Port to listen on
    #[arg(short, long, default_value_t = 7788)]
    port: u16,

    /// Don't open browser on start
    #[arg(long)]
    no_open: bool,

    /// Path to static web assets (web/dist/)
    #[arg(long, default_value = "web/dist")]
    dist: String,

    /// Log directory
    #[arg(long, default_value = "logs")]
    log_dir: String,

    /// Enable release mode (reduced stdout logging, info-level file logging)
    #[arg(long)]
    release_mode: bool,
}

#[tokio::main]
async fn main() {
    raise_fd_limit();

    let args = Args::parse();

    // Initialize logging — guards must live until program exit
    let _log_guards = logging::init(&args.log_dir, args.release_mode);

    // Install panic hook — crash reports written to crash.log
    let log_path = std::path::PathBuf::from(&args.log_dir);
    panic_hook::install(&log_path);

    // Start file watcher (background thread)
    let watcher_tx = watcher::start_watching();

    let api = router::build_api_router(watcher_tx, args.log_dir.clone());

    let index_path = std::path::PathBuf::from(&args.dist).join("index.html");
    let spa_fallback = tower::service_fn(move |_req: http::Request<_>| {
        let index = index_path.clone();
        async move {
            match tokio::fs::read(&index).await {
                Ok(body) => Ok(http::Response::builder()
                    .header("content-type", "text/html; charset=utf-8")
                    .header("cache-control", "no-cache, no-store, must-revalidate")
                    .body(axum::body::Body::from(body))
                    .unwrap()),
                Err(_) => Ok(http::Response::builder()
                    .status(404)
                    .body(axum::body::Body::from("index.html not found"))
                    .unwrap()),
            }
        }
    });

    let app = Router::new()
        .nest("/api", api)
        .fallback_service(
            ServeDir::new(&args.dist)
                .append_index_html_on_directories(true)
                .fallback(spa_fallback),
        )
        .layer(PropagateRequestIdLayer::x_request_id())
        .layer(
            TraceLayer::new_for_http()
                .make_span_with(|request: &http::Request<_>| {
                    let request_id = request
                        .headers()
                        .get("x-request-id")
                        .and_then(|v| v.to_str().ok())
                        .unwrap_or("none");
                    tracing::info_span!(
                        "http",
                        method = %request.method(),
                        path = %request.uri().path(),
                        request_id = %request_id,
                    )
                })
                .on_response(
                    tower_http::trace::DefaultOnResponse::new()
                        .level(tracing::Level::INFO)
                        .latency_unit(tower_http::LatencyUnit::Millis),
                )
                .on_failure(
                    tower_http::trace::DefaultOnFailure::new().level(tracing::Level::ERROR),
                ),
        )
        .layer(SetRequestIdLayer::x_request_id(MakeRequestUuid))
        .layer(CorsLayer::permissive());

    let addr = SocketAddr::from(([127, 0, 0, 1], args.port));
    tracing::info!("agent-panel-server listening on http://{}", addr);

    if !args.no_open {
        let url = format!("http://127.0.0.1:{}", args.port);
        let _ = open::that(&url);
    }

    let listener = tokio::net::TcpListener::bind(addr).await.unwrap();
    axum::serve(listener, app).await.unwrap();
}

/// Raise the file descriptor limit to avoid "Too many open files" when the
/// file watcher recursively monitors directories with many entries.
#[cfg(unix)]
fn raise_fd_limit() {
    use std::io;
    let mut rlim = libc::rlimit {
        rlim_cur: 0,
        rlim_max: 0,
    };
    unsafe {
        if libc::getrlimit(libc::RLIMIT_NOFILE, &mut rlim) == 0 {
            let target = rlim.rlim_max.min(10240);
            if rlim.rlim_cur < target {
                rlim.rlim_cur = target;
                if libc::setrlimit(libc::RLIMIT_NOFILE, &rlim) != 0 {
                    eprintln!(
                        "warning: failed to raise fd limit: {}",
                        io::Error::last_os_error()
                    );
                }
            }
        }
    }
}

#[cfg(not(unix))]
fn raise_fd_limit() {}

/// 测试工具模块
///
/// 提供共享的测试辅助函数，供 #[cfg(test)] 模块使用。
///
/// 用法：
/// ```rust
/// #[cfg(test)]
/// mod tests {
///     use crate::test_utils::*;
///
///     #[tokio::test]
///     async fn test_something() {
///         let (server, _dir) = create_test_server();
///         // ...
///     }
/// }
/// ```

use axum_test::TestServer;
use std::path::PathBuf;
use tempfile::TempDir;
use tokio::sync::broadcast;

use crate::router;

/// 创建隔离的测试服务器
pub fn create_test_server() -> (TestServer, TempDir) {
    let dir = TempDir::new().expect("failed to create temp dir");
    let (tx, _) = broadcast::channel(256);
    let api = router::build_api_router(tx, dir.path().to_str().unwrap().to_string());
    let server = TestServer::new(api.into_make_service());
    (server, dir)
}

/// 创建测试用的 JSONL session 文件
pub fn create_test_session_file(dir: &PathBuf, filename: &str, content: &str) -> PathBuf {
    let file_path = dir.join(filename);
    std::fs::write(&file_path, content).expect("failed to write test session file");
    file_path
}

/// 生成最小可用的 session JSONL 内容
pub fn sample_session_jsonl() -> String {
    let mut lines = Vec::new();

    lines.push(
        serde_json::json!({
            "type": "summary",
            "session_id": "test-session-001",
            "cwd": "/test/project",
            "git_branch": "main",
            "model": "claude-sonnet-4",
            "timestamp": "2026-01-01T00:00:00Z"
        })
        .to_string(),
    );

    lines.push(
        serde_json::json!({
            "type": "message",
            "uuid": "msg-001",
            "message": {
                "role": "user",
                "content": "Hello, test!"
            },
            "timestamp": "2026-01-01T00:00:01Z"
        })
