#[cfg(test)]
mod tests {
    use crate::test_utils::*;

    #[tokio::test]
    async fn test_favorites_list_empty() {
        let (server, _dir) = create_test_server();
        let res = server.get("/favorites").await;
        res.assert_status_ok();
        let body: serde_json::Value = res.json();
        assert!(body["favorites"].as_array().unwrap().is_empty());
    }

    #[tokio::test]
    async fn test_favorites_add_and_list() {
        let (server, _dir) = create_test_server();

        // Add a favorite
        let res = server
            .post("/favorites")
            .json(&serde_json::json!({
                "sessionId": "test-session-1",
                "messageId": "msg-1",
                "label": "test favorite"
            }))
            .await;
        res.assert_status_ok();

        // List favorites
        let res = server.get("/favorites").await;
        res.assert_status_ok();
        let body: serde_json::Value = res.json();
        assert_eq!(body["favorites"].as_array().unwrap().len(), 1);
    }

    #[tokio::test]
    async fn test_favorites_delete() {
        let (server, _dir) = create_test_server();

        // Add
        let res = server
            .post("/favorites")
            .json(&serde_json::json!({
                "sessionId": "test-session-1",
                "messageId": "msg-1"
            }))
            .await;
        res.assert_status_ok();
        let body: serde_json::Value = res.json();
        let id = body["id"].as_str().unwrap();

        // Delete
        let res = server.delete(&format!("/favorites/{}", id)).await;
        res.assert_status_ok();

        // Verify empty
        let res = server.get("/favorites").await;
        let body: serde_json::Value = res.json();
        assert!(body["favorites"].as_array().unwrap().is_empty());
    }

    #[tokio::test]
    async fn test_favorites_by_session() {
        let (server, _dir) = create_test_server();

        // Add favorite
        server
            .post("/favorites")
            .json(&serde_json::json!({
                "sessionId": "session-a",
                "messageId": "msg-1"
            }))
            .await;

        // Query by session
        let res = server.get("/favorites/session/session-a").await;
        res.assert_status_ok();
        let body: serde_json::Value = res.json();
        assert_eq!(body["favorites"].as_array().unwrap().len(), 1);
    }
}

