import { describe, it, expect, beforeEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { MemoryRouter } from 'react-router-dom';
import Dashboard from '../../src/pages/Dashboard';
import { resetState } from '../msw/state';

function renderDashboard() {
  const queryClient = new QueryClient({
    defaultOptions: { queries: { retry: false } },
  });
  return render(
    <QueryClientProvider client={queryClient}>
      <MemoryRouter>
        <Dashboard />
      </MemoryRouter>
    </QueryClientProvider>,
  );
}

describe('Dashboard', () => {
  beforeEach(() => resetState());

  it('renders the dashboard title', async () => {
    renderDashboard();
    await waitFor(() => {
      expect(screen.getByText(/Agent Panel|Dashboard|总览/)).toBeInTheDocument();
    });
  });

  it('displays stats cards', async () => {
    renderDashboard();
    await waitFor(() => {
      // Stats cards should show counts
      expect(screen.getByText(/Sessions|会话/)).toBeInTheDocument();
    });
  });

  it('renders without crashing', async () => {
    renderDashboard();
    await waitFor(() => {
      // Should not show loading forever
      expect(document.querySelector('.animate-pulse')).toBeFalsy();
    });
  });
});

